//! Validates the llama.rs quantization kernels against reference values
//! generated by `scripts/generate_reference_values.py`, an independent
//! Python translation of the ggml C reference routines.
//!
//! Regenerate with:
//! ```text
//! python3 scripts/generate_reference_values.py > tests/reference_values.json
//! ```

use std::collections::HashMap;

use llama_core::GgmlType;
use llama_kernels::quant::{QuantizedRow, dequantize_row};
use llama_kernels::vecdot;
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    blocks_hex: String,
    n_blocks: usize,
    q8_hex: String,
    expected_dequant: Vec<f32>,
    expected_dot: f32,
}

fn hex_to_bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("valid hex"))
        .collect()
}

fn parse_q8_row(bytes: &[u8]) -> QuantizedRow {
    let mut blocks = Vec::with_capacity(bytes.len() / 34);
    for b in 0..bytes.len() / 34 {
        let d = u16::from_le_bytes([bytes[b * 34], bytes[b * 34 + 1]]);
        let mut qs = [0i8; 32];
        for (j, slot) in qs.iter_mut().enumerate() {
            *slot = bytes[b * 34 + 2 + j] as i8;
        }
        blocks.push(llama_kernels::quant::BlockQ8_0 { d, qs });
    }
    QuantizedRow { blocks }
}

fn load_cases() -> HashMap<String, Case> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/reference_values.json");
    let data = std::fs::read_to_string(path).expect("reference_values.json present");
    serde_json::from_str(&data).expect("valid JSON")
}

fn check_case(name: &str, ty: GgmlType, case: &Case) {
    let bytes = hex_to_bytes(&case.blocks_hex);
    let n_elems = case.expected_dequant.len();
    assert_eq!(
        bytes.len(),
        case.n_blocks * ty.block_byte_size(),
        "{name}: block bytes"
    );

    // Dequantization.
    let mut out = vec![0.0f32; n_elems];
    dequantize_row(ty, &bytes, &mut out).expect("dequant supported");
    for (i, (got, want)) in out.iter().zip(case.expected_dequant.iter()).enumerate() {
        let tolerance = want.abs().max(1e-4) * 1e-4;
        assert!(
            (got - want).abs() <= tolerance,
            "{name}: dequant element {i}: got {got}, expected {want}"
        );
    }

    // Dot product against the reference-quantized activation.
    let q8_bytes = hex_to_bytes(&case.q8_hex);
    let xq = parse_q8_row(&q8_bytes);
    let got_dot = match ty {
        GgmlType::Q4_0 => vecdot::vec_dot_q4_0(&bytes, &xq),
        GgmlType::Q4_1 => vecdot::vec_dot_q4_1(&bytes, &xq),
        GgmlType::Q5_0 => vecdot::vec_dot_q5_0(&bytes, &xq),
        GgmlType::Q5_1 => vecdot::vec_dot_q5_1(&bytes, &xq),
        GgmlType::Q8_0 => vecdot::vec_dot_q8_0(&bytes, &xq),
        GgmlType::Q4_K => vecdot::vec_dot_q4_k(&bytes, &xq),
        GgmlType::Q5_K => vecdot::vec_dot_q5_k(&bytes, &xq),
        GgmlType::Q6_K => vecdot::vec_dot_q6_k(&bytes, &xq),
        other => panic!("unexpected type {other}"),
    };
    let want_dot = case.expected_dot;
    let tolerance = want_dot.abs().max(1.0) * 1e-3;
    assert!(
        (got_dot - want_dot).abs() <= tolerance,
        "{name}: vec_dot got {got_dot}, expected {want_dot}"
    );
}

#[test]
fn all_quant_types_match_reference() {
    let cases = load_cases();
    assert_eq!(
        cases.len(),
        8,
        "expected 8 quant types in the reference file"
    );
    check_case("q4_0", GgmlType::Q4_0, &cases["q4_0"]);
    check_case("q4_1", GgmlType::Q4_1, &cases["q4_1"]);
    check_case("q5_0", GgmlType::Q5_0, &cases["q5_0"]);
    check_case("q5_1", GgmlType::Q5_1, &cases["q5_1"]);
    check_case("q8_0", GgmlType::Q8_0, &cases["q8_0"]);
    check_case("q4_k", GgmlType::Q4_K, &cases["q4_k"]);
    check_case("q5_k", GgmlType::Q5_K, &cases["q5_k"]);
    check_case("q6_k", GgmlType::Q6_K, &cases["q6_k"]);
}
